#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> people(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> people[i][j];
        }
    }

    sort(people.begin(), people.end(), [](const vector<long long>& x, const vector<long long>& y) {
        if (x[0] != y[0]) return x[0] > y[0];
        return x[1] < y[1];
    });
    vector<vector<long long>> queue;
    for (const vector<long long>& p : people) queue.insert(queue.begin() + p[1], p);
    for (const vector<long long>& p : queue) cout << p[0] << " " << p[1] << "\n";

    return 0;
}

